import React, { useState, useEffect, useRef } from "react";
import axios from "axios";

// Swiper
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, EffectCoverflow } from "swiper";
import "swiper/css";
import "swiper/css/autoplay";
import "swiper/css/effect-coverflow";
import "animate.css";

// Styles
import "../Product_Video/productvideo.css";
// Image
import Background from "../assets/images/Rectangle20.webp";

const ProductVideos = () => {
  const [videos, setVideos] = useState([]);

  // Fetch YouTube video data
  useEffect(() => {
    const fetchVideos = async () => {
      try {
        const response = await axios.get(
          (process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/youtubeVideoList/"
        );
        if (response.data && response.data.data) {
          setVideos(response.data.data);
        }
      } catch (error) {
        console.error("Error fetching product videos:", error);
      }
    };
    fetchVideos();
  }, []);

  // Helper function to ensure YouTube URLs are in embed format
  const getEmbedUrl = (url) => {
    if (!url) return "";
    if (url.includes("embed")) {
      const separator = url.includes("?") ? "&" : "?";
      return `${url}${separator}enablejsapi=1&autoplay=1&mute=1`;
    }
    const id = getVideoId(url);
    return id ? `https://www.youtube.com/embed/${id}?autoplay=1&enablejsapi=1&mute=1` : url;
  };

  // Extract YouTube ID for thumbnail and embedding
  const getVideoId = (url) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const [activeVideo, setActiveVideo] = useState(null); // Track which video is playing
  const [isAutoplayEnabled, setIsAutoplayEnabled] = useState(true);
  const swiperRef = useRef(null);

  // Stop slider immediately when a video is opened
  useEffect(() => {
    if (activeVideo !== null) {
      setIsAutoplayEnabled(false);
    } else {
      setIsAutoplayEnabled(true);
    }
  }, [activeVideo]);

  // Listen for YouTube API messages to control Swiper autoplay
  useEffect(() => {
    const handleMessage = (event) => {
      if (!event.origin.includes("youtube.com")) return;

      try {
        const data = typeof event.data === "string" ? JSON.parse(event.data) : event.data;
        
        // Handle both "infoDelivery" and "onStateChange" formats
        let state = null;
        if (data.event === "infoDelivery" && data.info && data.info.playerState !== undefined) {
          state = data.info.playerState;
        } else if (data.event === "onStateChange") {
          state = data.info;
        }

        if (state !== null) {
          if (state === 1) { // Playing
            setIsAutoplayEnabled(false);
            if (swiperRef.current && swiperRef.current.autoplay) {
              swiperRef.current.autoplay.stop();
            }
          } else if (state === 2 || state === 0) { // Paused or Ended
            setIsAutoplayEnabled(true);
            if (swiperRef.current && swiperRef.current.autoplay) {
              swiperRef.current.autoplay.start();
            }
          }
        }
      } catch (e) {
        // Not a JSON message or not from YouTube API
      }
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, []);

  return (
    <div className="py-10">
      {/* Heading */}
      <div className="box h-[5rem] w-[25rem] relative flex justify-start items-start ml-[2rem] group mt-6 ">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-[18rem] duration-300 group"></div>
        <p className="text-[24px] absolute font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">
          Product Videos
        </p>
      </div>

      {/* Youtube video slider container */}
      <div
        className="product-video-wrapper w-full flex items-center justify-center bg-no-repeat bg-cover bg-center transition-opacity duration-700"
        style={{
          backgroundImage: `url(${Background})`,
          minHeight: "450px",
          opacity: videos.length > 0 ? 1 : 0.8,
        }}
      >
        {videos.length > 0 ? (
          <div className="w-full animate__animated animate__fadeIn">
            <Swiper
              effect="coverflow"
              grabCursor={true}
              centeredSlides={true}
              loop={videos.length >= 3}
              autoplay={isAutoplayEnabled ? {
                delay: 5000,
                disableOnInteraction: false,
              } : false}
              coverflowEffect={{
                rotate: 30,
                stretch: 0,
                depth: 100,
                modifier: 1,
                slideShadows: false,
              }}
              breakpoints={{
                320: { slidesPerView: 1 },
                640: { slidesPerView: 2 },
                1024: { slidesPerView: 3 },
              }}
              onSwiper={(swiper) => {
                swiperRef.current = swiper;
              }}
              onClick={(swiper) => {
                // Use Swiper's internal click handling to ensure it works on clones and with dragging
                if (swiper.clickedSlide) {
                  const slideIndex = swiper.clickedSlide.getAttribute('data-swiper-slide-index');
                  if (slideIndex !== null) {
                    setActiveVideo(parseInt(slideIndex));
                  }
                }
              }}
              slideToClickedSlide={true}
              modules={[EffectCoverflow, Autoplay]}
              className="mySwiper w-full py-10"
            >
              {videos.map((item, index) => {
                const videoId = getVideoId(item[1]);
                const isPlaying = activeVideo === index;
                
                return (
                  <SwiperSlide key={index} className="flex flex-col items-center">
                    <div className="w-[95%] mx-auto bg-black rounded-2xl overflow-hidden shadow-2xl border border-white/10 group/card flex flex-col cursor-pointer">
                      <div className="relative aspect-video">
                        {!isPlaying ? (
                          <div className="absolute inset-0 group/thumb">
                            {/* High-quality thumbnail */}
                            <img 
                              src={`https://img.youtube.com/vi/${videoId}/hqdefault.jpg`}
                              alt={item[0]}
                              className="w-full h-full object-cover transition-transform duration-500 group-hover/thumb:scale-105"
                              width="480"
                              height="270"
                              loading="lazy"
                            />
                          </div>
                        ) : (
                          <div className="absolute inset-0 animate__animated animate__fadeIn">
                            <iframe
                              className="w-full h-full"
                              src={getEmbedUrl(item[1])}
                              title={item[0]}
                              frameBorder="0"
                              referrerPolicy="strict-origin-when-cross-origin"
                              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                              allowFullScreen
                            ></iframe>
                            {/* Close button to resume slider easily */}
                            <button 
                              className="absolute top-2 right-2 bg-black/50 hover:bg-black/80 text-white w-8 h-8 rounded-full flex items-center justify-center z-10 transition-colors"
                              onClick={(e) => {
                                e.stopPropagation();
                                setActiveVideo(null);
                                setIsAutoplayEnabled(true);
                              }}
                            >
                              ✕
                            </button>
                          </div>
                        )}
                      </div>
                      {/* Title Footer */}
                      <div className="bg-[#0a0a0a] py-4 px-4 border-t border-white/10">
                        <h3 className="font-bold text-white text-center truncate px-2 text-[16px]" title={item[0]}>
                          {item[0]}
                        </h3>
                      </div>
                    </div>
                  </SwiperSlide>
                );
              })}
            </Swiper>
          </div>
        ) : (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#004B95]"></div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductVideos;
